// Cloudflare Workers entry for TokenFin.
// Serves the Next.js app via OpenNext and replaces Vercel Cron: each Cloudflare cron
// trigger calls the matching /api/v1/cron/* route with `Authorization: Bearer $CRON_SECRET`,
// exactly as Vercel Cron did, so the routes themselves are unchanged.
// @ts-ignore — generated by `opennextjs-cloudflare build`
import { default as handler } from './.open-next/worker.js'

// Must match `triggers.crons` in wrangler.jsonc (and the old vercel.json schedule).
const CRON_ROUTES: Record<string, string[]> = {
  '0 2 * * *':  ['/api/v1/cron/reconcile'],
  '30 2 * * *': ['/api/v1/cron/connectors'],
  '30 3 * * *': ['/api/v1/cron/retention', '/api/v1/cron/prices'],
  '0 4 * * *':  ['/api/v1/cron/alerts'],
  '0 5 * * 1':  ['/api/v1/cron/digest'],
}

type Env = { CRON_SECRET?: string; NEXT_PUBLIC_APP_URL?: string } & Record<string, unknown>

export default {
  fetch: handler.fetch,

  async scheduled(controller: ScheduledController, env: Env, ctx: ExecutionContext) {
    const paths = CRON_ROUTES[controller.cron] ?? []
    const base = env.NEXT_PUBLIC_APP_URL || 'https://tokenfin.curiousdevs.com'
    for (const path of paths) {
      const req = new Request(new URL(path, base), {
        headers: { authorization: `Bearer ${env.CRON_SECRET ?? ''}` },
      })
      ctx.waitUntil(
        handler.fetch(req, env, ctx).then(async (res: Response) => {
          console.log(`[cron] ${controller.cron} ${path} -> ${res.status}`)
        }),
      )
    }
  },
} satisfies ExportedHandler<Env>

// Re-export Durable Objects OpenNext may reference.
// @ts-ignore
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from './.open-next/worker.js'
